// A prism along x with an exact cross-section polygon [[z,y],...]; with sym the
// points are a half profile (z >= 0) from top centre to bottom centre.
function hhPrism(s,label,x0,x1,poly,opt={},sym=true,mirror=false){
 const pts=sym?poly.concat(poly.slice(1,-1).reverse().map(([z,y])=>[-z,y])):poly;
 const ys=pts.map(p=>p[1]),zs=pts.map(p=>p[0]),y0=Math.min(...ys),y1=Math.max(...ys),z0=Math.min(...zs),z1=Math.max(...zs),cy=(y0+y1)/2,cz=(z0+z1)/2;
 // pitch -90: local x is world -y, local y is world x, local z is world z.
 return placePart(s,'struct',[(x0+x1)/2,cy,cz],[y1-y0,z1-z0,x1-x0],{label,skin:'armor',form:'outline',outline:pts.map(([z,y])=>[(cy-y)/(y1-y0),(z-cz)/(z1-z0)]),corner:0,taper:0,pitch:-90,...opt},mirror);
}
// An elliptical-section loft along z (yaw 90): rows [z, xMin, xMax, yMin, yMax].
function hhRoundZ(s,label,rows,opt={},mirror=false){
 rows=rows.slice().sort((a,b)=>a[0]-b[0]);
 const z0=rows[0][0],z1=rows.at(-1)[0],X0=Math.min(...rows.map(r=>r[1])),X1=Math.max(...rows.map(r=>r[2])),Y0=Math.min(...rows.map(r=>r[3])),Y1=Math.max(...rows.map(r=>r[4]));
 const L=z1-z0,W=X1-X0,H=Y1-Y0,cx=(X0+X1)/2;
 const loft=rows.map(r=>[(r[0]-z0)/L,(r[2]-r[1])/W,(r[4]-Y0)/H,(r[3]-Y0)/H,-((r[1]+r[2])/2-cx)/(W/2)]);
 return placePart(s,'struct',[cx,(Y0+Y1)/2,(z0+z1)/2],[L,W,H],{label,skin:'armor',form:'roundloft',yaw:90,loft,...opt},mirror);
}
// A plate standing in the x-y plane (side-view outline [[x,y],...]) from z0 to z1.
function hhPlateXY(s,label,pts,z0,z1,opt={},mirror=false){
 const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys),cx=(x0+x1)/2,cy=(y0+y1)/2;
 // roll 90: local x is world x, local y (the plate's thickness) is world z, local z is world -y.
 return placePart(s,'struct',[cx,cy,(z0+z1)/2],[x1-x0,y1-y0,z1-z0],{label,skin:'armor',form:'outline',outline:pts.map(([x,y])=>[(x-cx)/(x1-x0),(cy-y)/(y1-y0)]),corner:0,taper:0,roll:90,...opt},mirror);
}
// Weapon placement with ground and step checks (as for the Acclamator).
function hhMountKit(s,opt={}){
 const tryMount=(kind,p,axis,zone,o={})=>{const f={id:s.nextId++,k:kind,p:p.slice(),a:axis,ped:0,base:0,low:0,float:false,batteryZone:zone,...o};mountFit(s,f);const why=f._onPlate?'plate':f.float?'float':(f.base-f.low)>(o.maxStep??fitSpec(f).fm*.6)?'steep':'';if(opt.dbg)opt.dbg.push([kind,zone,p.map(v=>Math.round(v*10)/10).join(','),why||'ok',f.p.map(v=>Math.round(v*10)/10).join(',')]);if(why){s.nextId--;throw new Error('作例の砲座が不正です: '+kind+' '+zone+' '+why);}s.fits.push(f);return f;};
 return {tryMount};
}
function hhBuild(opt={}){
 const D=HH,L=116.7;
 const s=newShip({L,W:D.W,H:D.H,sec:'warship',plan:'wedge',deckWidth:0,keelWidth:0,belt:.2,chineHeight:.5,bowFree:true,stations:D.st.map(a=>a.slice()),keel:'light'},'ハンマーヘッド級コルベット');
 s._building=true;s.reference='hammerhead';s.paint='republic';s.lights='white';s.detail=1;s.armor={hull:.2,cit:.2};s.shieldTarget=1;
 const k=shipKit(s),part=(kind,label,c,d,o={},mirror=false)=>placePart(s,kind,c,d,{label,...o},mirror),room=(kind,label,c,size,o={},mirror=false)=>part(kind,label,c,30,{room:size,...o},mirror);
 const tidy=p=>{for(const q of s.parts.filter(q=>q.id===p.id||q.id===p.tw))q.loft=q.loft.map(r=>r.map(v=>Math.round(v*1e9)/1e9));return p;};
 const tidyO=p=>{for(const q of s.parts.filter(q=>q.id===p.id||q.id===p.tw))q.outline=q.outline.map(r=>r.map(v=>Math.round(v*1e9)/1e9));return p;};
 if(opt.stage==='hull'){delete s._building;return s;}
 // ---- the engine block: three pylon-mounted engine nacelles on an inverted Y-shaped block ----
 tidy(k.loftX('上部機関ナセル',D.upper,{round:true},true));
 tidy(k.loftX('下部機関ナセル',D.lower,{round:true}));
 tidyO(hhPrism(s,'Y字形機関ブロック',10.8,35.8,D.yplate));
 tidy(k.loftX('艦尾中央板',D.stern,{corner:.1}));
 k.box('艦尾中央板上部の張り出し',[9.16,23.91,-5.09],[11.16,26.48,5.09]);
 k.box('機関ブロック背部の箱',[11.26,26.02,-3.46],[21.38,28.2,3.46]);
 // ---- the transverse drum, the turret base and the dorsal turret's pillar at the front of the block ----
 tidy(hhRoundZ(s,'横置き円筒（機関ブロック前端）',D.collar));
 k.put('背部砲塔基部',[35.81,27.33,0],[13.8,13.8,5.14],{form:'cylinder'});
 k.put('背部砲塔基部の上縁',[35.81,31.065,0],[13.8,13.8,2.33],{form:'cone',taper:.333});
 tidy(k.loftX('背部砲塔の支柱',D.pillar,{corner:.08}));
 // ---- fittings along the cylindrical hull ----
 tidy(k.loftX('背部円筒',D.spine,{round:true}));
 tidy(k.loftX('背部覆い',D.cover,{round:true}));
 tidy(k.loftX('腹部円筒',D.vcyl,{round:true}));
 tidy(k.loftX('腹部箱桁',D.vbox,{corner:.05}));
 k.box('腹部板',[66.18,14.82,-3.15],[89.79,16.82,3.15]);
 for(const x of [66.42,87.5])k.box('腹部側面の継手',[x,15.5,1.98],[x+2,19.53,3.98],{},true);
 tidyO(k.slab('側面安定板',[[40.38,6.0],[40.38,11.65],[43.3,11.65],[51.31,6.0]],22.06,24.06,{},true));
 // ---- the neck and the hammer prow: the cockpit band across the prow, the swept upper edge,
 // the edge fins and the reinforced leading edges (armour plate for ramming) ----
 tidy(hhRoundZ(s,'首部の横置き円筒',D.neck));
 k.box('首部背面の箱',[94.16,26.02,-4.57],[99.18,28.2,4.57]);
 k.box('首部腹面の箱',[93.83,12.6,-3.43],[97.53,17.14,3.43]);
 tidyO(hhPlateXY(s,'艦首上部の後退縁',D.swept,-2.5,2.5));
 tidy(k.loftX('操縦区画帯（艦首）',D.band,{corner:.04}));
 tidyO(hhPlateXY(s,'艦首上縁の鰭',D.topfin,-1,1));
 tidyO(hhPlateXY(s,'艦首下縁の鰭',D.botfin,-1.78,1.78));
 tidy(k.loftX('強化艦首装甲（衝角）',D.prow,{corner:.1,plate:true,plateT:.6}));
 if(opt.stage==='shape'){delete s._building;return s;}
 // ---- machinery: the engine block houses the main reactor, the hyperdrive and most engineering ----
 const gen=part('gen','主反応炉',[25,18.5,0],14);   // v21.1 14 m (was 13): carries the full-size guns at their full rate
 const eng=(label,front,y,z,d,mirror)=>part('engine',label,[front/2,y,z],d,{dir:[-1,0,0],nozzleLength:front,bodyLength:2,bodyRadius:.4,reactor:gen.id},mirror);
 eng('上部イオン機関',30.5,23.15,10.27,7.6,true);
 eng('下部イオン機関',42.5,6.6,0,8,false);
 part('hyper','ハイパードライブ',[14,20.5,0],4.4,{length:HH_HYPER_LENGTH,dir:[1,0,0]});
 // The reactant silo runs along the ventral cylinder; the feed plant sits at the front of the block.
 part('fuel','反応物サイロ（腹部円筒）',[50,15.6,0],4.4,{length:24,dir:[1,0,0]});
 room('pump','反応物供給設備',[35.8,22,0],[4,4,4]);
 // The inertial compensator stands in the turret base; the structural integrity field
 // generators sit in the ends of the transverse drum.
 part('inertial','慣性補償装置',[35.8,27.5,0],10,{length:5,dir:[0,1,0]});
 room('integrity','構造維持フィールド発生装置',[36.2,23.08,13.7],[5.8,4.2,5.8],{},true);
 // Modular cargo holds in the cylindrical hull.
 for(const [i,x0,x1] of [[1,41.5,63.5],[2,64,79],[3,80,95.5]])room('cargo','モジュール式貨物倉 '+i,[(x0+x1)/2,21.9,0],[x1-x0,8,8]);
 // Powerful forward shields: the generator in the hammer prow; the sensor at its top.
 part('shield','前方シールド発生器',[101.5,36.5,0],6.8);
 part('sensor','中距離センサー',[102,44.2,0],4.2);
 // The spacious cockpit at the front of the prow (four crew stations).
 room('command','操縦室（飛行甲板）',[110.3,22.6,0],[6,8,6]);
 if(opt.stage==='machinery'){delete s._building;return s;}
 const {tryMount}=hhMountKit(s,opt);
 syncAviationSurfaces(s);s._lockedCache=cache(s);
 try{withFrozenStructures(()=>{
  // The dorsal turret-mounted twin light turbolaser battery at the engine block.
  tryMount('ltl',[32.7,0,0],2,'dorsal');
  // Two dual heavy laser cannons on the sides of the prow beside the cockpit, firing forward.
  tryMount('pd',[101.4,22.2,0],4,'bow-stbd');
  tryMount('pd',[101.4,22.2,0],5,'bow-port');
 });}finally{delete s._lockedCache;}
 if(opt.stage==='fitted'){delete s._building;return s;}
 s.airWings=[];s.groundForces=normalizeGroundForces(HH_GROUND);
 delete s._building;adoptEquipment(s,true);remount(s);syncCompartments(s);
 return s;
}
