   const ps=mode==='beam'?[[[x,off,far],4],[[x,off,-far],5]]:(off?[1,-1]:[1]).map(sg=>[[x,0,sg*off],mode==='top'?2:3]);
   if(got+ps.length>n)continue;const fs=[];
