const BAND_KEYS = ['deep', 'core', 'colonies', 'inner', 'expansion', 'mid', 'outer', 'unknown'];
function sideName(side) { return side.next ? `${BY[side.next].name}方面` : `${REGIONS[BAND_KEYS[bandAt(side.end)]].name}方面`; }
